CREATE TABLE IF NOT EXISTS businesses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'INR',legal_name VARCHAR(190) NULL,gst_registration_type ENUM('Regular','Composition','Unregistered') NOT NULL DEFAULT 'Unregistered',gstin VARCHAR(15) NULL,address VARCHAR(255) NULL,city VARCHAR(100) NULL,state VARCHAR(100) NULL,state_code CHAR(2) NULL,postal_code VARCHAR(20) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id BIGINT UNSIGNED NOT NULL,name VARCHAR(190) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('owner','manager') NOT NULL DEFAULT 'manager',active TINYINT(1) NOT NULL DEFAULT 1,last_login_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_users_business FOREIGN KEY(business_id) REFERENCES businesses(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS customers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id BIGINT UNSIGNED NOT NULL,name VARCHAR(190) NOT NULL,company VARCHAR(190) NULL,email VARCHAR(190) NULL,phone VARCHAR(40) NULL,city VARCHAR(100) NULL,gstin VARCHAR(32) NULL,address VARCHAR(255) NULL,state VARCHAR(100) NULL,state_code CHAR(2) NULL,postal_code VARCHAR(20) NULL,notes TEXT NULL,archived_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(business_id,archived_at),CONSTRAINT fk_customers_business FOREIGN KEY(business_id) REFERENCES businesses(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS leads (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id BIGINT UNSIGNED NOT NULL,name VARCHAR(190) NOT NULL,company VARCHAR(190) NULL,email VARCHAR(190) NULL,phone VARCHAR(40) NULL,source VARCHAR(80) NULL,stage VARCHAR(60) NOT NULL DEFAULT 'New',status ENUM('Open','Won','Lost') NOT NULL DEFAULT 'Open',deal_value DECIMAL(14,2) NOT NULL DEFAULT 0,expected_close DATE NULL,follow_up DATE NULL,notes TEXT NULL,converted_customer_id BIGINT UNSIGNED NULL,converted_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(business_id,status),CONSTRAINT fk_leads_business FOREIGN KEY(business_id) REFERENCES businesses(id),CONSTRAINT fk_leads_converted_customer FOREIGN KEY(converted_customer_id) REFERENCES customers(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id BIGINT UNSIGNED NOT NULL,name VARCHAR(190) NOT NULL,sku VARCHAR(80) NULL,hsn_sac VARCHAR(20) NULL,kind ENUM('Product','Service') NOT NULL DEFAULT 'Service',category VARCHAR(100) NULL,unit VARCHAR(40) NOT NULL DEFAULT 'unit',price DECIMAL(14,2) NOT NULL DEFAULT 0,tax_rate DECIMAL(6,3) NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(business_id,active),CONSTRAINT fk_products_business FOREIGN KEY(business_id) REFERENCES businesses(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS tasks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id BIGINT UNSIGNED NOT NULL,customer_id BIGINT UNSIGNED NULL,title VARCHAR(255) NOT NULL,description TEXT NULL,priority ENUM('Low','Medium','High') NOT NULL DEFAULT 'Medium',status ENUM('Pending','In Progress','Completed','Cancelled') NOT NULL DEFAULT 'Pending',due_date DATE NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(business_id,status,due_date),CONSTRAINT fk_tasks_business FOREIGN KEY(business_id) REFERENCES businesses(id),CONSTRAINT fk_tasks_customer FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS invoices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id BIGINT UNSIGNED NOT NULL,customer_id BIGINT UNSIGNED NOT NULL,invoice_number VARCHAR(60) NOT NULL,invoice_date DATE NOT NULL,due_date DATE NULL,status ENUM('Draft','Issued','Partially Paid','Paid','Overdue','Void') NOT NULL DEFAULT 'Issued',document_type ENUM('Standard Invoice','GST Tax Invoice','Bill of Supply') NOT NULL DEFAULT 'Standard Invoice',place_of_supply_state VARCHAR(100) NULL,place_of_supply_code CHAR(2) NULL,reverse_charge TINYINT(1) NOT NULL DEFAULT 0,subtotal DECIMAL(14,2) NOT NULL DEFAULT 0,tax_total DECIMAL(14,2) NOT NULL DEFAULT 0,total DECIMAL(14,2) NOT NULL DEFAULT 0,amount_paid DECIMAL(14,2) NOT NULL DEFAULT 0,customer_snapshot JSON NULL,business_snapshot JSON NULL,notes TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_invoice_number(business_id,invoice_number),INDEX(business_id,status),CONSTRAINT fk_invoices_business FOREIGN KEY(business_id) REFERENCES businesses(id),CONSTRAINT fk_invoices_customer FOREIGN KEY(customer_id) REFERENCES customers(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS invoice_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NULL,description VARCHAR(255) NOT NULL,hsn_sac VARCHAR(20) NULL,quantity DECIMAL(12,3) NOT NULL,unit VARCHAR(40) NULL,unit_price DECIMAL(14,2) NOT NULL,tax_rate DECIMAL(6,3) NOT NULL DEFAULT 0,cgst_rate DECIMAL(6,3) NOT NULL DEFAULT 0,sgst_rate DECIMAL(6,3) NOT NULL DEFAULT 0,igst_rate DECIMAL(6,3) NOT NULL DEFAULT 0,line_subtotal DECIMAL(14,2) NOT NULL,line_tax DECIMAL(14,2) NOT NULL,cgst_amount DECIMAL(14,2) NOT NULL DEFAULT 0,sgst_amount DECIMAL(14,2) NOT NULL DEFAULT 0,igst_amount DECIMAL(14,2) NOT NULL DEFAULT 0,line_total DECIMAL(14,2) NOT NULL,CONSTRAINT fk_invoice_items_invoice FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE CASCADE,CONSTRAINT fk_invoice_items_product FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id BIGINT UNSIGNED NOT NULL,invoice_id BIGINT UNSIGNED NOT NULL,customer_id BIGINT UNSIGNED NOT NULL,paid_at DATE NOT NULL,amount DECIMAL(14,2) NOT NULL,method ENUM('Cash','Bank transfer','UPI','Card','Cheque','Other') NOT NULL DEFAULT 'Bank transfer',reference VARCHAR(120) NULL,notes TEXT NULL,reversed_at DATETIME NULL,reversed_by BIGINT UNSIGNED NULL,reversal_note VARCHAR(500) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(business_id,paid_at),CONSTRAINT fk_payments_business FOREIGN KEY(business_id) REFERENCES businesses(id),CONSTRAINT fk_payments_invoice FOREIGN KEY(invoice_id) REFERENCES invoices(id),CONSTRAINT fk_payments_customer FOREIGN KEY(customer_id) REFERENCES customers(id),CONSTRAINT fk_payments_reversed_by FOREIGN KEY(reversed_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS expenses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id BIGINT UNSIGNED NOT NULL,expense_date DATE NOT NULL,category VARCHAR(100) NOT NULL,description VARCHAR(255) NOT NULL,amount DECIMAL(14,2) NOT NULL,method VARCHAR(60) NOT NULL DEFAULT 'Bank transfer',vendor VARCHAR(190) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(business_id,expense_date),CONSTRAINT fk_expenses_business FOREIGN KEY(business_id) REFERENCES businesses(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS activity_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,event VARCHAR(100) NOT NULL,detail VARCHAR(500) NULL,ip_address VARCHAR(45) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(created_at),CONSTRAINT fk_activity_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS user_permissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,permission_key VARCHAR(100) NOT NULL,granted TINYINT(1) NOT NULL DEFAULT 0,UNIQUE KEY uq_user_permission(user_id,permission_key),CONSTRAINT fk_user_permissions_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS quotations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id BIGINT UNSIGNED NOT NULL,customer_id BIGINT UNSIGNED NOT NULL,quotation_number VARCHAR(60) NOT NULL,quotation_date DATE NOT NULL,valid_until DATE NULL,status ENUM('Draft','Sent','Accepted','Rejected','Expired','Converted') NOT NULL DEFAULT 'Draft',subtotal DECIMAL(14,2) NOT NULL DEFAULT 0,tax_total DECIMAL(14,2) NOT NULL DEFAULT 0,total DECIMAL(14,2) NOT NULL DEFAULT 0,customer_snapshot JSON NULL,business_snapshot JSON NULL,notes TEXT NULL,invoice_id BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_quotation_number(business_id,quotation_number),INDEX(business_id,status),CONSTRAINT fk_quotations_business FOREIGN KEY(business_id) REFERENCES businesses(id),CONSTRAINT fk_quotations_customer FOREIGN KEY(customer_id) REFERENCES customers(id),CONSTRAINT fk_quotations_invoice FOREIGN KEY(invoice_id) REFERENCES invoices(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS quotation_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,quotation_id BIGINT UNSIGNED NOT NULL,description VARCHAR(255) NOT NULL,quantity DECIMAL(12,3) NOT NULL,unit VARCHAR(40) NULL,unit_price DECIMAL(14,2) NOT NULL,tax_rate DECIMAL(6,3) NOT NULL DEFAULT 0,line_subtotal DECIMAL(14,2) NOT NULL,line_tax DECIMAL(14,2) NOT NULL,line_total DECIMAL(14,2) NOT NULL,CONSTRAINT fk_quotation_items_quotation FOREIGN KEY(quotation_id) REFERENCES quotations(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS password_reset_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,expires_at),CONSTRAINT fk_password_reset_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
